  id: string;
  name: string;
}

export function parseUser(raw: string): Result<User, string> {
  let data: any;
  try {
    data = JSON.parse(raw);
  } catch {
    return err('invalid JSON');
  }
  if (!data.id || !data.name) {
    return err('missing required fields');
  }
  return ok({ id: data.id, name: data.name });
}

