import { legacyFetch } from './httpClient';

/**
 * User profile data access module.
 *
 * This module encapsulates userprofile-related network calls plus the
 * client-side validation, normalization, and formatting logic that sits
 * around them. It follows the same thin-data-access-layer shape used by
 * the other modules in this directory; see the sibling files for the same
 * pattern applied to other domains.
 */

export interface UserProfile {
  id: string;
  displayName: string;
  loginCount: number;
  archived: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface UserProfileQueryOptions {
  includeArchived?: boolean;
  limit?: number;
  offset?: number;
  sortBy?: keyof UserProfile;
}

export interface UserProfileValidationError {
  field: string;
  message: string;
}

const DEFAULT_LIMIT = 50;
const MAX_LIMIT = 200;
const MIN_LIMIT = 1;

/**
 * Clamp a requested page size to the allowed [MIN_LIMIT, MAX_LIMIT] range,
 * falling back to DEFAULT_LIMIT when the caller doesn't specify one.
 */
function clampLimit(limit?: number): number {
  if (limit === undefined) {
    return DEFAULT_LIMIT;
  }
  if (limit < MIN_LIMIT) {
    return MIN_LIMIT;
  }
  if (limit > MAX_LIMIT) {
    return MAX_LIMIT;
  }
  return limit;
}

/**
 * Build the query string for a userprofile listing request from the
 * caller-supplied options object.
 */
function buildQueryString(options: UserProfileQueryOptions): string {
  const params = new URLSearchParams();
  params.set('limit', String(clampLimit(options.limit)));
  if (options.offset) {
    params.set('offset', String(options.offset));
  }
  if (options.includeArchived) {
    params.set('includeArchived', 'true');
  }
  if (options.sortBy) {
    params.set('sortBy', String(options.sortBy));
  }
  return params.toString();
}

/**
 * Validate a partial userprofile payload before it is sent to the server.
 * Returns an empty array when the payload passes every check.
 */
function validateUserProfile(payload: Partial<UserProfile>): UserProfileValidationError[] {
  const errors: UserProfileValidationError[] = [];
  if (payload.displayName !== undefined && payload.displayName.trim().length === 0) {
    errors.push({ field: 'displayName', message: 'displayName must not be empty' });
  }
  if (payload.loginCount !== undefined && payload.loginCount < 0) {
    errors.push({ field: 'loginCount', message: 'loginCount must not be negative' });
  }
  return errors;
}

/**
 * Normalize a raw server record into the shape the rest of the app expects.
 * Server responses are loosely typed, so this is where we pin down types.
 */
function normalizeUserProfile(raw: any): UserProfile {
  return {
    id: String(raw.id),
    displayName: String(raw.displayName ?? ''),
    loginCount: Number(raw.loginCount ?? 0),
    archived: Boolean(raw.archived ?? false),
    createdAt: String(raw.createdAt ?? ''),
    updatedAt: String(raw.updatedAt ?? ''),
  };
}

/**
 * Group a list of userprofiles by their archived flag. Handy for list
 * views that split active vs. archived records into separate sections.
 */
function partitionByArchived(items: UserProfile[]): { active: UserProfile[]; archived: UserProfile[] } {
  const active: UserProfile[] = [];
  const archived: UserProfile[] = [];
  for (const item of items) {
    if (item.archived) {
      archived.push(item);
    } else {
      active.push(item);
    }
  }
  return { active, archived };
}

/**
 * Thin client wrapping the userprofile endpoints. Kept as a class so
 * callers can hold a single instance and, eventually, inject a mock for
 * tests without touching every call site.
 */
export class UserProfileClient {
  private readonly basePath: string;

  constructor(basePath = '/api/userProfiles') {
    this.basePath = basePath;
  }

  /**
   * Fetch a single userprofile by id. Throws if the server responds with
   * a non-2xx status; callers are expected to catch and translate.
   */
  async getById(id: string): Promise<UserProfile> {
    const raw = await this.request(`${this.basePath}/${id}`);
    return normalizeUserProfile(raw);
  }

  /**
   * List userProfiles matching the given query options, most-recent first
   * unless the caller overrides sortBy.
   */
  async list(options: UserProfileQueryOptions = {}): Promise<UserProfile[]> {
    const qs = buildQueryString(options);
    const raw = await this.request(`${this.basePath}?${qs}`);
    return Array.isArray(raw) ? raw.map(normalizeUserProfile) : [];
  }

  /**
   * List only the active (non-archived) userProfiles. Convenience wrapper
   * around list() + partitionByArchived() for the common case.
   */
  async listActive(options: UserProfileQueryOptions = {}): Promise<UserProfile[]> {
    const all = await this.list({ ...options, includeArchived: true });
    return partitionByArchived(all).active;
  }

  /**
   * Low-level request helper. This still goes through the deprecated
   * legacyFetch wrapper pending the migration to the retry-aware client;
   * see the tracking ticket for the rollout plan.
   */
  private async request(path: string): Promise<any> {
    return legacyFetch(path);
  }

  /**
   * Create a new userprofile. Validates locally before hitting the
   * network so we don't round-trip on obviously bad input.
   */
  async create(payload: Partial<UserProfile>): Promise<UserProfile> {
    const errors = validateUserProfile(payload);
    if (errors.length > 0) {
      throw new Error(`invalid userprofile: ${errors.map((e) => e.message).join(', ')}`);
    }
    const raw = await this.requestWithBody(this.basePath, 'POST', payload);
    return normalizeUserProfile(raw);
  }

  /**
   * Archive a userprofile rather than deleting it outright, so it can
   * still be recovered from an admin tool later.
   */
  async archive(id: string): Promise<UserProfile> {
    const raw = await this.requestWithBody(`${this.basePath}/${id}/archive`, 'POST', {});
    return normalizeUserProfile(raw);
  }

  /**
   * Placeholder for the future retry-aware client. Not wired up yet; the
   * legacy path above is still what production traffic uses.
   */
  private async requestWithBody(path: string, method: string, body: unknown): Promise<any> {
    throw new Error(`requestWithBody is not implemented for the legacy userprofile client (path=${path}, method=${method})`);
  }
}

/**
 * Format a short human-readable summary line for a userprofile, used in
 * list rows and log messages.
 */
export function formatUserProfileSummary(entity: UserProfile): string {
  return `${entity.displayName} (#${entity.id})`;
}

/**
 * Sort userProfiles oldest-first by their createdAt timestamp.
 */
export function sortByCreatedAt(items: UserProfile[]): UserProfile[] {
  return [...items].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

/**
 * Sum the loginCount field across a list of userProfiles. Used by dashboard
 * summary widgets.
 */
export function sumByLoginCount(items: UserProfile[]): number {
  return items.reduce((total, item) => total + item.loginCount, 0);
}

export const defaultUserProfileClient = new UserProfileClient();

